import json, pathlib, re
manifest_path = '/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54mini_all/first_10_queries/q09/logs/q09.manifest.json'
out_path = '/mnt/data/LSF/baseline_results/court/agentic_codex_qa_gpt54mini_all/first_10_queries/q09/logs/q09.answers.json'
manifest = json.load(open(manifest_path))
question = manifest['questions'][0]
answers = {}
for d in manifest['documents']:
    txt = pathlib.Path(d['doc_path']).read_text(errors='ignore')
    ans = None
    m = re.search(r'"'^(?:Amended'"\\s+)?Opinion by Judge\\s+(.+?)(?:;|"'$)'"', txt, re.M)
    if m:
        ans = m.group(1).strip()
    else:
        m = re.search(r'"'^(?:Amended'"\\s+)?Opinion by\\s+(.+?)(?:;|"'$)'"', txt, re.M)
        if m:
            ans = m.group(1).strip()
    if ans is None:
        m = re.search(r'"'^(?:Per Curiam Opinion|PER CURIAM|Per Curiam)(?:[:;.]|$)'"', txt, re.M)
        if m:
            ans = 'Per Curiam'
    if ans is None:
        ans = 'NOT_FOUND'
    answers[d['doc_name']] = {question: ans}
obj = {'answers': answers}
with open(out_path, 'w') as f:
    json.dump(obj, f, indent=2, sort_keys=True)
    f.write('\\n')
print('wrote', out_path)
print('docs', len(answers))
print('sample', list(answers.items())[:3])
